import { useEffect } from "react";

// OpenNotch's landing page is a self-contained static site (its own canvas,
// live three.js companion and video) that lives in public/opennotch/ and is
// served as-is at /opennotch/. This route only hands in-app navigation over to
// it with a full page load, so it renders exactly as designed — outside the
// portfolio shell.
//
// Production: GitHub Pages serves public/opennotch/index.html for /opennotch/.
// Dev (npm start): the dev server would send /opennotch/ back to the SPA, so
// point at the file itself to avoid a redirect loop.
const TARGET =
  process.env.NODE_ENV === "production"
    ? "/opennotch/"
    : "/opennotch/index.html";

export default function NotchPage() {
  useEffect(() => {
    window.location.replace(TARGET);
  }, []);

  return (
    <div style={{ minHeight: "60vh", display: "grid", placeItems: "center", color: "inherit" }}>
      <a href={TARGET}>Opening OpenNotch…</a>
    </div>
  );
}
